`DecisionPrompt` represents a one-shot localized decision. The constructor trims `title` and `message` and throws `RangeError` if either is empty. Supported locales are `en`, `es`, and `fr`; unsupported or blank locale strings fall back to `en`. Labels are respectively `Confirm`/`Cancel`, `Confirmar`/`Cancelar`, and `Confirmer`/`Annuler`. `snapshot` returns a fresh object. `confirm()` closes an open prompt and returns true. `cancel()` closes an open prompt and returns false. After either operation, both methods return undefined and do not change the stored result. `result()` is undefined while open and then remains the first decision.

Known-bad source:

export interface PromptSnapshot {
  readonly title: string;
  readonly message: string;
  readonly confirmLabel: string;
  readonly cancelLabel: string;
  readonly open: boolean;
}

export class DecisionPrompt {
  private open = true;
  private decision: boolean | undefined;
  private readonly data: Omit<PromptSnapshot, "open">;

  constructor(title: string, message: string, locale: string) {
    const normalizedTitle = title.trim();
    const normalizedMessage = message.trim();
    if (normalizedTitle.length === 0 || normalizedMessage.length === 0) {
      throw new RangeError("Prompt text cannot be empty");
    }
    const labels: Record<string, readonly [string, string]> = {
      en: ["Confirm", "Cancel"],
      es: ["Confirmar", "Cancelar"],
      fr: ["Confirmer", "Annuler"],
    };
    const pair = labels[locale.trim()] ?? labels.en;
    this.data = {
      title: normalizedTitle,
      message: normalizedMessage,
      confirmLabel: pair[0],
      cancelLabel: pair[1],
    };
  }

  snapshot(): PromptSnapshot {
    return { ...this.data, open: this.open };
  }

  confirm(): boolean | undefined {
    return this.close(true);
  }

  cancel(): boolean | undefined {
    return this.close(true);
  }

  result(): boolean | undefined {
    return this.decision;
  }

  private close(value: boolean): boolean | undefined {
    if (!this.open) return undefined;
    this.open = false;
    this.decision = value;
    return value;
  }
}

