import { DecisionPrompt } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal<T>(actual: T, expected: T, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function rangeError(action: () => void, message: string): void {
  try { action(); } catch (error) {
    if (error instanceof RangeError) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: expected RangeError`);
}

rangeError(() => new DecisionPrompt(' ', 'message', 'en'), 'blank title');
rangeError(() => new DecisionPrompt('title', '\t', 'en'), 'blank message');

const labels: readonly [string, string, string][] = [
  ['en', 'Confirm', 'Cancel'],
  ['es', 'Confirmar', 'Cancelar'],
  ['fr', 'Confirmer', 'Annuler'],
  ['de', 'Confirm', 'Cancel'],
  [' ', 'Confirm', 'Cancel'],
];
for (const [locale, confirmLabel, cancelLabel] of labels) {
  const prompt = new DecisionPrompt(' T ', ' M ', locale);
  const snapshot = prompt.snapshot();
  equal(snapshot.title, 'T', `title trimmed for ${locale}`);
  equal(snapshot.message, 'M', `message trimmed for ${locale}`);
  equal(snapshot.confirmLabel, confirmLabel, `confirm label for ${locale}`);
  equal(snapshot.cancelLabel, cancelLabel, `cancel label for ${locale}`);
  equal(snapshot.open, true, `prompt starts open for ${locale}`);
  equal(prompt.result(), undefined, `result absent while open for ${locale}`);
}

const confirmed = new DecisionPrompt('Title', 'Message', 'en');
const firstSnapshot = confirmed.snapshot();
const secondSnapshot = confirmed.snapshot();
assert(firstSnapshot !== secondSnapshot, 'snapshots are fresh');
(firstSnapshot as { title: string; open: boolean }).title = 'changed';
(firstSnapshot as { title: string; open: boolean }).open = false;
equal(confirmed.snapshot().title, 'Title', 'snapshot mutation cannot alter title');
equal(confirmed.snapshot().open, true, 'snapshot mutation cannot close prompt');
equal(confirmed.confirm(), true, 'confirm closes with true');
equal(confirmed.snapshot().open, false, 'confirmed prompt is closed');
equal(confirmed.result(), true, 'confirmed result persists');
equal(confirmed.cancel(), undefined, 'cancel after confirm does nothing');
equal(confirmed.confirm(), undefined, 'confirm is one-shot');
equal(confirmed.result(), true, 'later calls do not change first result');

const cancelled = new DecisionPrompt('Title', 'Message', 'es');
equal(cancelled.cancel(), false, 'cancel closes with false');
equal(cancelled.snapshot().open, false, 'cancelled prompt is closed');
equal(cancelled.result(), false, 'cancelled result persists');
equal(cancelled.confirm(), undefined, 'confirm after cancel does nothing');
equal(cancelled.cancel(), undefined, 'cancel is one-shot');
equal(cancelled.result(), false, 'first false decision remains stored');

